import time
import random

def construct():
    start_time = time.time()
    deadline = start_time + 50.0  # 10s margin from 60s limit
    n = 4096
    
    def can_add(x, selected, sums):
        # Check sums involving x
        # 1. 3x
        if 3*x in sums:
            return False
        # 2. 2x + s
        for s in selected:
            if 2*x + s in sums:
                return False
        # 3. x + s + t
        # We need to check all pairs (s, t) from selected, s <= t
        # Note: The triple is unordered, so {x, s, t} is the same as {s, x, t} etc.
        # The sums generated by adding x to existing set S are:
        # - {x, x, x} -> 3x
        # - {x, x, s} -> 2x + s for s in S
        # - {x, s, t} -> x + s + t for s, t in S, s <= t
        # We must ensure these new sums are not in the existing sums set.
        # Also, we must ensure the new sums themselves are unique.
        # Since x is new, 3x, 2x+s, x+s+t are distinct from each other?
        # 3x = 2x+s => x=s. But x is not in S, so 3x != 2x+s.
        # 3x = x+s+t => 2x = s+t. Possible? If s+t=2x, then {x,x,x} and {x,s,t} have same sum.
        # 2x+s = 2x+t => s=t.
        # 2x+s = x+t+u => x+s = t+u.
        # x+s+t = x+s'+t' => s+t = s'+t'.
        # Since S is a valid B_3[1] set, all sums from S are unique.
        # We just need to check if any new sum collides with existing sums.
        
        # Optimization: Generate new sums and check against 'sums'.
        # Also check for collisions among new sums?
        # If we add x, the new sums are $N_x = \{3x\} \cup \{2x+s \mid s \in S\} \cup \{x+s+t \mid s,t \in S, s \le t\}$.
        # We need $N_x \cap \text{sums} = \emptyset$ and $N_x$ to be a set (no duplicates within $N_x$).
        
        new_sums = set()
        
        # 1. 3x
        s_val = 3*x
        if s_val in sums:
            return False
        if s_val in new_sums:
            return False
        new_sums.add(s_val)
        
        # 2. 2x + s
        for s in selected:
            s_val = 2*x + s
            if s_val in sums:
                return False
            if s_val in new_sums:
                return False
            new_sums.add(s_val)
        
        # 3. x + s + t
        k = len(selected)
        for i in range(k):
            s = selected[i]
            for j in range(i, k):
                t = selected[j]
                s_val = x + s + t
                if s_val in sums:
                    return False
                if s_val in new_sums:
                    return False
                new_sums.add(s_val)
                
        return True

    def add_x(x, selected, sums):
        selected.append(x)
        sums.add(3*x)
        for s in selected[:-1]:
            sums.add(2*x + s)
        k = len(selected)
        for i in range(k-1):
            s = selected[i]
            for j in range(i, k-1):
                t = selected[j]
                sums.add(x + s + t)

    def greedy_forward():
        selected = []
        sums = set()
        for x in range(1, n + 1):
            if time.time() > deadline:
                break
            if can_add(x, selected, sums):
                add_x(x, selected, sums)
        return selected

    def greedy_backward():
        selected = []
        sums = set()
        # Start from large numbers
        for x in range(n, 0, -1):
            if time.time() > deadline:
                break
            if can_add(x, selected, sums):
                add_x(x, selected, sums)
        return selected

    def greedy_randomized(start_range=1000, window=20):
        selected = []
        sums = set()
        # Start with a random small set or just random picks?
        # Let's try picking from a sliding window of candidates.
        # This is tricky to implement efficiently without pre-computing feasibility.
        # Alternative: Randomly shuffle the order of candidates? No, that's slow.
        
        # Strategy: Pick the first feasible x, but with some randomness in the search order?
        # Or: Restart with a random offset?
        
        # Let's try a "Random Start" greedy:
        # Pick a random starting point r, then greedily add neighbors?
        # Simpler: Just run forward greedy but skip some numbers randomly?
        
        # Actually, a better randomization is to try different "density" levels.
        # But let's stick to Forward and Backward for now, as they are distinct structural approaches.
        
        # Let's add a "Sparse" greedy: only consider multiples of some step?
        # No, that restricts the set too much.
        
        return selected

    best_set = []
    
    # 1. Forward Greedy
    s1 = greedy_forward()
    if len(s1) > len(best_set):
        best_set = s1
    
    if time.time() > deadline:
        return best_set

    # 2. Backward Greedy
    s2 = greedy_backward()
    if len(s2) > len(best_set):
        best_set = s2

    if time.time() > deadline:
        return best_set

    # 3. Randomized Restarts
    # Try a few random permutations of the "greedy choice" or random starts.
    # A simple randomization: Shuffle the list of candidates [1..4096] and greedily pick?
    # That is $O(N^2)$ per restart. $N=4096$, $N^2 \approx 1.6 \times 10^7$.
    # If we do 10 restarts, that's $1.6 \times 10^8$ operations. Might be too slow in Python.
    
    # Better: Randomized "Forward" with a random step size or random skipping.
    # Or: Run greedy, but at each step, if there are multiple feasible candidates in a small window, pick one randomly.
    # Since we iterate 1..N, there's only one candidate at a time.
    
    # Let's try "Randomized Backward":
    # Iterate from N down to 1, but with a random probability of skipping?
    
    # Let's try a different structure:
    # Start with a random set of size k, then try to expand?
    
    # Given time constraints, let's try a few random "Perturbations" of the Forward Greedy.
    # Idea: In Forward Greedy, we always pick the smallest feasible x.
    # What if we pick a random feasible x from the range [current_min, current_min + W]?
    # This requires scanning forward to find feasible candidates.
    
    def greedy_windowed(window_size=100):
        selected = []
        sums = set()
        current_min = 1
        while current_min <= n:
            if time.time() > deadline:
                break
            
            # Find all feasible x in [current_min, current_min + window_size]
            candidates = []
            for x in range(current_min, min(n, current_min + window_size) + 1):
                if can_add(x, selected, sums):
                    candidates.append(x)
            
            if not candidates:
                # No candidates in this window. Move forward?
                # If we skip this window, we might miss a valid set.
                # But for a heuristic, it's okay.
                current_min += window_size
                continue
            
            # Pick a random candidate from the feasible ones
            x = random.choice(candidates)
            add_x(x, selected, sums)
            # Move the window forward past x
            current_min = x + 1
            
        return selected

    # Run a few windowed greedy instances
    for _ in range(5):
        if time.time() > deadline:
            break
        s_rand = greedy_windowed(window_size=50)
        if len(s_rand) > len(best_set):
            best_set = s_rand

    return best_set
